// Input from agent, e.g. [{ "input": "CNC making unusual noise", "workstation_id": "WS-01" }]
const issue = $input[0]?.input ?? "Unspecified issue";
const workstationId = $input[0]?.workstation_id ?? "Unknown";
const timestamp = new Date().toISOString();
const escalationId = `ESC-${Date.now()}`;

// Step 1: Log the issue
const log = {
  step: "logged",
  escalation_id: escalationId,
  workstation_id: workstationId,
  issue: issue,
  timestamp: timestamp
};

// Step 2: Simulate notifying supervisor (message/call)
const notify = {
  step: "supervisor_notified",
  method: "message", // could be "call" in a real system if urgency flag is added
  supervisor: "Shift Supervisor",
  status: "delivered",
  timestamp: new Date().toISOString()
};

const result = {
  escalation_id: escalationId,
  workstation_id: workstationId,
  issue: issue,
  log_status: log.step,
  notification_status: notify.status,
  notified_via: notify.method,
  source: "Escalation Log"
};

return JSON.stringify(result);
